#include "wire_protocol.h"
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <string.h>
static void packet(FILE *f,const void *a,unsigned n,const void *b,unsigned m){uint32_t size=n+m;assert(fwrite(&size,4,1,f)==1);assert(fwrite(a,1,n,f)==n);if(m)assert(fwrite(b,1,m,f)==m);}
int main(int argc,char **argv){assert(argc==2);assert(d2_crc32((const uint8_t*)"123456789",9)==0xcbf43926);assert(d2_crc32(NULL,0)==0);for(int hd=0;hd<2;hd++){char path[1024];snprintf(path,sizeof(path),"%s/%s.bin",argv[1],hd?"hd":"low");FILE*f=fopen(path,"wb");assert(f);uint8_t*p=malloc(STREAM_MAX_BYTES);assert(p);for(unsigned i=0;i<STREAM_PAYLOAD_BYTES;i++)p[i]=(uint8_t)(i*13+7);for(unsigned i=0;i<GUIDE_PAYLOAD_BYTES;i++)p[STREAM_PAYLOAD_BYTES+i]=(uint8_t)(i*17+(i>>10)*31+37);
 stream_header_t h={.magic=STREAM_MAGIC,.version=2,.header_bytes=64,.frame_id=0xfffffff0,.style_epoch=0xfedcba98,.sequence=0x98765432,.timestamp_ms=123456,.style_id=2,.effect=1,.quality=(uint8_t)hd,.flags=3,.source_fps_x100=6000,.width=256,.height=144,.guide_width=hd?1920:0,.guide_height=hd?1080:0,.algorithm=(uint16_t)hd,.style_bytes=STREAM_PAYLOAD_BYTES,.guide_bytes=hd?GUIDE_PAYLOAD_BYTES:0,.style_crc32=d2_crc32(p,STREAM_PAYLOAD_BYTES),.guide_crc32=hd?d2_crc32(p+STREAM_PAYLOAD_BYTES,GUIDE_PAYLOAD_BYTES):0,.stream_session=0x12345678};h.header_crc32=d2_crc32((const uint8_t*)&h,60);packet(f,&h,64,NULL,0);
 for(unsigned plane=0;plane<2;plane++){unsigned total=plane?h.guide_bytes:h.style_bytes;uint8_t *base=p+(plane?STREAM_PAYLOAD_BYTES:0);for(unsigned off=0;off<total;off+=STREAM_CHUNK_BYTES){unsigned n=total-off;if(n>STREAM_CHUNK_BYTES)n=STREAM_CHUNK_BYTES;stream_chunk_t c={.magic=CHUNK_MAGIC,.sequence=h.sequence,.frame_id=h.frame_id,.style_epoch=h.style_epoch,.plane=(uint8_t)plane,.bytes=(uint16_t)n,.offset=off,.payload_crc32=d2_crc32(base+off,n)};c.header_crc32=d2_crc32((const uint8_t*)&c,28);packet(f,&c,32,base+off,n);}}
 stream_end_t e={.magic=END_MAGIC,.sequence=h.sequence,.frame_id=h.frame_id,.style_epoch=h.style_epoch,.style_crc32=h.style_crc32,.guide_crc32=h.guide_crc32,.total_bytes=h.style_bytes+h.guide_bytes};e.header_crc32=d2_crc32((const uint8_t*)&e,28);packet(f,&e,32,NULL,0);fclose(f);free(p);}puts("PASS: production packedC headers/IEEECRC fullHD/low wirefixtures");return 0;}
